import StorageCore
import SwiftUI

/// The hand-inked illustrations in `Assets.xcassets/Illustrations`.
/// They're generated by `ios/Tools/illustrations/generate.py`; each has a
/// light and a dark variant that the asset catalog switches automatically.
enum Illustration: String, CaseIterable {
    case beaker = "ill-beaker"
    case compress = "ill-compress"
    case emptyBox = "ill-empty-box"
    case lock = "ill-lock"
    case phoneSparkle = "ill-phone-sparkle"
    case photo = "ill-photo"
    case piggy = "ill-piggy"
    case reset = "ill-reset"
    case screenshot = "ill-screenshot"
    case shieldCheck = "ill-shield-check"
    case stackLarge = "ill-stack-large"
    case stackSmall = "ill-stack-small"
    case trash = "ill-trash"
    case umbrella = "ill-umbrella"
    case video = "ill-video"

    static func forCategory(_ category: MediaCategory) -> Illustration {
        switch category {
        case .photo: .photo
        case .video: .video
        case .screenshot: .screenshot
        }
    }

    static func forScenario(_ scenario: DemoScenario) -> Illustration {
        switch scenario {
        case .typical: .stackSmall
        case .large: .stackLarge
        case .empty: .emptyBox
        }
    }
}

/// Shows an illustration at a fixed size. Decorative by default, so VoiceOver skips it.
struct IllustrationView: View {
    let illustration: Illustration
    var size: CGFloat = 56

    init(_ illustration: Illustration, size: CGFloat = 56) {
        self.illustration = illustration
        self.size = size
    }

    var body: some View {
        Image(illustration.rawValue)
            .resizable()
            .interpolation(.high)
            .scaledToFit()
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}

/// A hand-drawn wavy underline, used under the headline savings figure.
struct Squiggle: Shape {
    var waves: Int = 7

    func path(in rect: CGRect) -> Path {
        var path = Path()
        let step = rect.width / CGFloat(waves * 2)
        path.move(to: CGPoint(x: rect.minX, y: rect.midY))
        for i in 0..<(waves * 2) {
            let x = rect.minX + step * CGFloat(i + 1)
            let control = CGPoint(x: x - step / 2, y: i.isMultiple(of: 2) ? rect.minY : rect.maxY)
            path.addQuadCurve(to: CGPoint(x: x, y: rect.midY), control: control)
        }
        return path
    }
}

#Preview("Illustrations") {
    ScrollView {
        LazyVGrid(columns: [GridItem(.adaptive(minimum: 80))], spacing: 20) {
            ForEach(Illustration.allCases, id: \.self) { item in
                VStack {
                    IllustrationView(item, size: 64)
                    Text(item.rawValue).font(.caption2).foregroundStyle(.secondary)
                }
            }
        }
        .padding()
        Squiggle().stroke(Theme.mint, style: StrokeStyle(lineWidth: 3, lineCap: .round)).frame(width: 160, height: 8)
    }
    .background(Theme.background)
}
